import random
from typing import List, Tuple, Dict, Optional
from games.base import BaseGame

class CooperativeNavigationGame(BaseGame):
    """
    A game where two players must navigate to the same set of target positions
    using only verbal descriptions of their moves.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.grid_size = 5  # 5x5 grid
        self.target_positions = self._generate_target_positions()
        self.player_positions = {player: (0, 0) for player in self.players}
        self.player_paths = {player: [(0, 0)] for player in self.players}
        self.visited_targets = {player: set() for player in self.players}
        self.max_turns = 20
        self.turn_count = 0
        self.game_active = False

    def _generate_target_positions(self) -> List[Tuple[int, int]]:
        """Generate random target positions on the grid."""
        positions = []
        while len(positions) < 3:  # 3 target positions
            pos = (random.randint(0, self.grid_size - 1), random.randint(0, self.grid_size - 1))
            if pos not in positions:
                positions.append(pos)
        return positions

    def initialize_game(self) -> None:
        """Initialize the game state."""
        self.target_positions = self._generate_target_positions()
        for player in self.players:
            self.player_positions[player] = (0, 0)
            self.player_paths[player] = [(0, 0)]
            self.visited_targets[player] = set()
        self.turn_count = 0
        self.game_active = True

    def get_game_state(self) -> Dict:
        """Return the current game state."""
        return {
            "grid_size": self.grid_size,
            "target_positions": self.target_positions,
            "player_positions": self.player_positions,
            "current_player": self.current_player,
            "turn_count": self.turn_count,
            "max_turns": self.max_turns,
            "game_active": self.game_active,
            "visited_targets": self.visited_targets,
        }

    def validate_move(self, player: str, move: str) -> Tuple[bool, str]:
        """Validate the player's move description."""
        if not self.game_active:
            return False, "Game is not active."

        if player != self.current_player:
            return False, "It's not your turn."

        if not move.strip():
            return False, "Move description cannot be empty."

        return True, ""

    def execute_move(self, player: str, move: str) -> Tuple[bool, str]:
        """Execute the player's move based on their description."""
        valid, message = self.validate_move(player, move)
        if not valid:
            return False, message

        current_pos = self.player_positions[player]
        new_pos = self._interpret_move_description(move, current_pos)

        if new_pos is None:
            return False, "Could not understand your move. Please describe your direction more clearly."

        # Check if the move is valid
        if not self._is_valid_move(new_pos):
            return False, "Invalid move. You can only move one step in any direction."

        # Update player position
        self.player_positions[player] = new_pos
        self.player_paths[player].append(new_pos)

        # Check if player reached a target
        if new_pos in self.target_positions:
            self.visited_targets[player].add(new_pos)

        # Check if both players have visited all targets
        if all(len(visited) == len(self.target_positions) for visited in self.visited_targets.values()):
            self.game_active = False
            return True, "Both players have visited all targets! Game over."

        self.turn_count += 1
        if self.turn_count >= self.max_turns:
            self.game_active = False
            return True, "Maximum turns reached. Game over."

        # Switch to the other player
        self.current_player = self.players[1] if player == self.players[0] else self.players[0]
        return True, f"Move executed. Now it's {self.current_player}'s turn."

    def _is_valid_move(self, position: Tuple[int, int]) -> bool:
        """Check if the move is valid (within grid bounds and one step away)."""
        x, y = position
        if not (0 <= x < self.grid_size and 0 <= y < self.grid_size):
            return False

        current_x, current_y = self.player_positions[self.current_player]
        return abs(x - current_x) <= 1 and abs(y - current_y) <= 1 and (x != current_x or y != current_y)

    def _interpret_move_description(self, description: str, current_pos: Tuple[int, int]) -> Optional[Tuple[int, int]]:
        """Try to interpret the player's move description."""
        description = description.lower()
        x, y = current_pos

        # Check for simple direction words
        if "up" in description or "شىمال" in description or "北" in description:
            return (x, y - 1)
        elif "down" in description or "جەنۇب" in description or "南" in description:
            return (x, y + 1)
        elif "left" in description or "غەرب" in description or "西" in description:
            return (x - 1, y)
        elif "right" in description or "شەرق" in description or "东" in description:
            return (x + 1, y)
        elif "northeast" in description or "شىمال شەرق" in description or "东北" in description:
            return (x + 1, y - 1)
        elif "northwest" in description or "شىمال غەرب" in description or "西北" in description:
            return (x - 1, y - 1)
        elif "southeast" in description or "جەنۇب شەرق" in description or "东南" in description:
            return (x + 1, y + 1)
        elif "southwest" in description or "جەنۇب غەرب" in description or "西南" in description:
            return (x - 1, y + 1)

        # Check for relative descriptions
        if "forward" in description:
            # Assume forward is the direction of the last move
            if len(self.player_paths[player]) > 1:
                last_move = (
                    self.player_paths[player][-1][0] - self.player_paths[player][-2][0],
                    self.player_paths[player][-1][1] - self.player_paths[player][-2][1],
                )
                return (x + last_move[0], y + last_move[1])

        return None

    def get_winner(self) -> Optional[str]:
        """Determine the winner of the game."""
        if not self.game_active and all(len(visited) == len(self.target_positions) for visited in self.visited_targets.values()):
            return "Both players"  # Both win if they've visited all targets
        return None

    def get_instructions(self) -> str:
        """Return the game instructions."""
        return """
        Cooperative Navigation Game Instructions:

        1. You and another player are on a 5x5 grid.
        2. There are 3 target positions that both of you need to visit.
        3. You cannot see the grid or each other's positions.
        4. On your turn, describe your intended move (e.g., "move up", "go right").
        5. You can only move one step in any direction (including diagonals).
        6. The game ends when both players have visited all target positions or after 20

