            return False

        current_x, current_y = self.player_positions[self.current_player]
        return abs(x - current_x) <= 1 and abs(y - current_y) <= 1 and (x != current_x or y != current_y)

    def _interpret_move_description(self, description: str, current_pos: Tuple[int, int]) -> Optional[Tuple[int, int]]:
        """Try to interpret the player's move description."""
