        elif "right" in description or "شەرق" in description or "东" in description:
            return (x + 1, y)
        elif "northeast" in description or "شىمال شەرق" in description or "东北" in description:
            return (x + 1, y - 1)
        elif "northwest" in description or "شىمال غەرب" in description or "西北" in description:
