        new_pos = self._interpret_move_description(move, current_pos)

        if new_pos is None:
            return False, "Could not understand your move. Please describe your direction more clearly."

        # Check if the move is valid
        if not self._is_valid_move(new_pos):
            return False, "Invalid move. You can only move one step in any direction."

        # Update player position
        self.player_positions[player] = new_pos
        self.player_paths[player].append(new_pos)

        # Check if player reached a target
        if new_pos in self.target_positions:
            self.visited_targets[player].add(new_pos)

