from typing import List, Dict, Tuple, Optional, Set
from games.base import BaseGame
import random

class CrosswordConstructionGame(BaseGame):
    """
    A cooperative game where two players work together to construct a crossword puzzle.
    One player provides clues, and the other tries to fill in the answers.
    """

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.grid_size = 5
        self.grid: List[List[str]] = [['' for _ in range(self.grid_size)] for _ in range(self.grid_size)]
        self.clues: Dict[Tuple[int, int, str], str] = {}  # (x, y, direction): clue
        self.answers: Dict[Tuple[int, int, str], str] = {}  # (x, y, direction): answer
        self.used_words: Set[str] = set()
        self.current_cluer: Optional[str] = None
        self.current_guesser: Optional[str] = None
        self.max_turns = 20
        self.turn_count = 0
        self.game_active = False

    def initialize_game(self) -> None:
        """Initialize the game with random words and assign roles."""
        self.grid = [['' for _ in range(self.grid_size)] for _ in range(self.grid_size)]
        self.clues = {}
        self.answers = {}
        self.used_words = set()
        self.turn_count = 0
        self.game_active = True

        # Assign roles
        self.current_cluer = self.players[0]
        self.current_guesser = self.players[1]

        # Generate some random words for the crossword
        self._generate_initial_words()

    def _generate_initial_words(self) -> None:
        """Generate some initial words for the crossword."""
        word_list = [
            "apple", "brave", "crane", "dance", "eagle",
            "fruit", "grape", "happy", "igloo", "jolly",
            "lemon", "melon", "noble", "olive", "peach"
        ]

        # Select 3-5 random words
        selected_words = random.sample(word_list, random.randint(3, 5))
        for word in selected_words:
            self.used_words.add(word)

        # Place the first word horizontally in the center
        center = self.grid_size // 2
        first_word = selected_words[0]
        for i, letter in enumerate(first_word):
            self.grid[center][center - len(first_word) // 2 + i] = letter
        self.answers[(center - len(first_word) // 2, center, 'across')] = first_word

        # Try to place other words
        for word in selected_words[1:]:
            self._try_place_word(word)

    def _try_place_word(self, word: str) -> bool:
        """Try to place a word in the grid."""
        # Find possible intersections
        for y in range(self.grid_size):
            for x in range(self.grid_size):
                if self.grid[y][x] != '':
                    # Check if we can place the word vertically
                    if self._can_place_word(word, x, y, 'down'):
                        self._place_word(word, x, y, 'down')
                        return True
                    # Check if we can place the word horizontally
                    if self._can_place_word(word, x, y, 'across'):
                        self._place_word(word, x, y, 'across')
                        return True
        return False

    def _can_place_word(self, word: str, x: int, y: int, direction: str) -> bool:
        """Check if a word can be placed at the given position."""
        if direction == 'across':
            if x + len(word) > self.grid_size:
                return False
            for i in range(len(word)):
                if self.grid[y][x + i] != '' and self.grid[y][x + i] != word[i]:
                    return False
        elif direction == 'down':
            if y + len(word) > self.grid_size:
                return False
            for i in range(len(word)):
                if self.grid[y + i][x] != '' and self.grid[y + i][x] != word[i]:
                    return False
        return True

    def _place_word(self, word: str, x: int, y: int, direction: str) -> None:
        """Place a word in the grid."""
        if direction == 'across':
            for i in range(len(word)):
                self.grid[y][x + i] = word[i]
            self.answers[(x, y, 'across')] = word
        elif direction == 'down':
            for i in range(len(word)):
                self.grid[y + i][x] = word[i]
            self.answers[(x, y, 'down')] = word

    def get_game_state(self) -> Dict:
        """Return the current game state."""
        return {
            "grid": self.grid,
            "clues": self.clues,
            "current_cluer": self.current_cluer,
            "current_guesser": self.current_guesser,
            "turn_count": self.turn_count,
            "max_turns": self.max_turns,
            "game_active": self.game_active,
            "used_words": list(self.used_words),
        }

    def validate_move(self, player: str, move: str) -> Tuple[bool, str]:
        """Validate the player's move."""
        if not self.game_active:
            return False, "Game is not active."

        if player not in [self.current_cluer, self.current_guesser]:
            return False, "It's not your turn."

        if not move.strip():
            return False, "Move cannot be empty."

        return True, ""

    def execute_move(self, player: str, move: str) -> Tuple[bool, str]:
        """Execute the player's move."""
        valid, message = self.validate_move(player, move)
