from typing import Dict, Any, Optional
from games import create_game
import logging

class GameManager:
    """Manages game instances and their states."""

    def __init__(self):
        self.active_games: Dict[str, Any] = {}
        self.logger = logging.getLogger(__name__)

    def create_game(self, game_name: str, player_names: list) -> Dict[str, Any]:
        """Create a new game instance."""
        try:
            game_id = f"game_{len(self.active_games) + 1}"
            game = create_game(game_name, player_names)
            game.initialize_game()
            self.active_games[game_id] = game

            # Get the initial game state
            game_state = game.get_game_state()
            game_state['game_id'] = game_id
            game_state['instructions'] = game.get_instructions()

            return {
                "status": "success",
                "message": "Game created successfully",
                "game_state": game_state
            }
        except ValueError as e:
            self.logger.error(f"Error creating game: {str(e)}")
            return {
                "status": "error",
                "message": str(e)
            }
        except Exception as e:
            self.logger.error(f"Unexpected error creating game: {str(e)}")
            return {
                "status": "error",
                "message": "An unexpected error occurred while creating the game"
            }

    def make_move(self, game_id: str, player_name: str, move: str) -> Dict[str, Any]:
        """Make a move in an existing game."""
        if game_id not in self.active_games:
            return {
                "status": "error",
                "message": "Game not found"
            }

        game = self.active_games[game_id]

        # Check if it's the player's turn
        if game.current_player != player_name:
            return {
                "status": "error",
                "message": f"It's not {player_name}'s turn. Current turn: {game.current_player}"
            }

        try:
            # Execute the move
            success, message = game.execute_move(player_name, move)

            if not success:
                # Add penalty if the move was invalid
                game.add_penalty(player_name)
                return {
                    "status": "error",
                    "message": message,
                    "penalties": game.get_penalties(player_name)
                }

            # Get the updated game state
            game_state = game.get_game_state()
            game_state['game_id'] = game_id

            # Check if game is over
            if game.is_game_over():
                winner = game.get_winner()
                return {
                    "status": "game_over",
                    "message": message,
                    "game_state": game_state,
                    "winner": winner
                }

            return {
                "status": "success",
                "message": message,
                "game_state": game_state
            }
        except Exception as e:
            self.logger.error(f"Error making move: {str(e)}")
            return {
                "status": "error",
                "message": f"An error occurred while processing your move: {str(e)}"
            }

    def get_game_state(self, game_id: str) -> Dict[str, Any]:
        """Get the current state of a game."""
        if game_id not in self.active_games:
            return {
                "status": "error",
                "message": "Game not found"
            }

        game = self.active_games[game_id]
        game_state = game.get_game_state()
        game_state['game_id'] = game_id

        return {
            "status": "success",
            "game_state": game_state
        }

    def get_instructions(self, game_id: str) -> Dict[str, Any]:
        """Get the instructions for a game."""
        if game_id not in self.active_games:
            return {
                "status": "error",
                "message": "Game not found"
            }

        game = self.active_games[game_id]
        return {
            "status": "success",
            "instructions": game.get_instructions()
        }

    def get_penalties(self, game_id: str, player_name: str) -> Dict[str, Any]:
        """Get the penalties for a player in a game."""
        if game_id not in self.active_games:
            return {
                "status": "error",
                "message": "Game not found"
            }

        game = self.active_games[game_id]
        return {
            "status": "success",
            "penalties": game.get_penalties(player_name)
        }

    def delete_game(self, game_id: str) -> Dict[str, Any]:
        """Delete a game instance."""
        if game_id in self.active_games:
            del self.active_games[game_id]
            return {
                "status": "success",
                "message": "Game deleted successfully"
            }
        return {
            "status": "error",
            "message": "Game not found"
        }
